const i = $input.first().json;
const notes = (i['Scope notes (everything from the call, freeform)'] || '').trim();
if (notes.length < 100) {
  return [{ json: { halt: true, reason: 'scope_notes_too_short', detail: `Need ≥100 chars; got ${notes.length}.` } }];
}
return [{ json: {
  halt: false,
  lead_id: i['Krayin lead ID'],
  sku: i['SKU'],
  scope_notes: notes
} }];

const fs = require('fs');
const yaml = require('js-yaml');

const formData = $('Validate scope notes length').first().json;
const lead = $input.first().json;

const skuYaml = fs.readFileSync('/data/templates/skus.yml', 'utf8');
const catalog = yaml.load(skuYaml);
const sku = catalog.skus.find(s => s.sku === formData.sku);
if (!sku) throw new Error(`Unknown SKU: ${formData.sku}`);

const template = fs.readFileSync(`/data/templates/proposals/${sku.template}`, 'utf8');
const sharedFooter = fs.readFileSync('/data/templates/proposals/_shared-footer.md', 'utf8');
const prompt = fs.readFileSync('/data/prompts/proposal-generation.md', 'utf8');

return [{ json: {
  ...formData,
  lead,
  sku_record: sku,
  template,
  shared_footer: sharedFooter,
  prompt_source: prompt,
  today: new Date().toISOString().slice(0, 10)
} }];

