const r = $input.first().json;
const ctx = $('Load SKU + template from disk').first().json;

let text = r.content?.[0]?.text || '';
text = text.replace(/^```json\s*|\s*```$/g, '').trim();

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { return [{ json: { halt: true, reason: 'claude_invalid_json', detail: text.slice(0, 300) } }]; }

if (parsed.needs_more_info) {
  return [{ json: { halt: true, reason: 'needs_more_info', detail: (parsed.missing_info || []).join('; ') } }];
}

const sumLines = (parsed.line_items || []).reduce((s, l) => s + (l.aed || 0), 0);
if (sumLines !== parsed.total_aed) {
  return [{ json: { halt: true, reason: 'total_aed_mismatch', detail: `sum=${sumLines} total=${parsed.total_aed}` } }];
}

const [pmin, pmax] = ctx.sku_record.price_range_aed;
if (parsed.total_aed > pmax) {
  const flagged = (parsed.rationale || '').toLowerCase().includes('scope larger') || (parsed.rationale || '').toLowerCase().includes('review price');
  if (!flagged) return [{ json: { halt: true, reason: 'price_above_max_unflagged', detail: `total=${parsed.total_aed} max=${pmax}; rationale missing scope-expansion flag` } }];
}

return [{ json: { ...ctx, claude: parsed, halt: false, usage: r.usage } }];

// n8n HTTP node replaces $json with response; re-merge upstream context
const render = $input.first().json;
const ctx = $('parse-and-validate').first().json;
if (!render || !render.ok) {
  throw new Error(`render failed: ${render && render.reason ? render.reason : 'unknown'}`);
}
return [{ json: {
  ...ctx,
  proposal_ref: render.proposal_ref,
  pdf_base64:   render.pdf_base64,
  pdf_size:     render.pdf_size
} }];
